from pathlib import Path
import base64, io, tarfile
DATA=''
root=Path('.')
raw=base64.b64decode(DATA)
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as tf:
    tf.extractall(root)
index=root/'index.html'
text=index.read_text(encoding='utf-8')
if 'auth-controls.js' not in text:
    text=text.replace('</body>','<script src="auth-controls.js"></script></body>')
    index.write_text(text,encoding='utf-8')
readme=root/'README.md'
if readme.exists():
    txt=readme.read_text(encoding='utf-8')
    marker='## Autenticação na Vercel'
    if marker not in txt:
        txt += '\n\n## Autenticação na Vercel\n\nO repositório inclui uma camada stateless de autenticação por e-mail para deploy na Vercel. A lista de e-mails autorizados e os segredos ficam em variáveis de ambiente, nunca no frontend. Consulte `documentacao/AUTENTICACAO-E-DEPLOY-VERCEL.md`.\n'
        readme.write_text(txt,encoding='utf-8')
print('auth files generated')